def env_bool(value, default=False):
    if value is None:
        return default
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in ('false', '0', 'no', 'off'):
            return False
        if normalized in ('true', '1', 'yes', 'on'):
            return True
        return default
    return bool(value)

def load(env):
    return {'debug': env_bool(env.get('APP_DEBUG'), False)}
